static GLOBAL_CONFIG_OVERRIDES: Mutex<Vec<GlobalConfigOverride>> = Mutex::new(Vec::new());
static GLOBAL_GIT_DIR: Mutex<Option<PathBuf>> = Mutex::new(None);
static GLOBAL_WORK_TREE: Mutex<Option<PathBuf>> = Mutex::new(None);
static GLOBAL_BARE: Mutex<bool> = Mutex::new(false);

fn main() {
    if let Err(err) = run(env::args().skip(1).collect()) {
        if let GitError::Exit(code) = err {
            std::process::exit(code);
        }
        eprintln!("git-rs: {err}");
        std::process::exit(1);
    }
}

fn run(args: Vec<String>) -> Result<()> {
    let global = apply_global_options(&args)?;
    set_global_config_overrides(global.config.clone());
    set_global_git_dir(global.git_dir.clone());
    set_global_work_tree(global.work_tree.clone());
    set_global_bare(global.bare);
    let args = global.args;
    let Some(command) = args.first().map(String::as_str) else {
        print_usage();
        return Err(GitError::Command("missing command".into()));
    };
    match command {
        "init" => cmd_init(&args[1..], &global.config),
        "add" => cmd_add(&args[1..]),
        "branch" => cmd_branch(&args[1..]),
        "bundle" => cmd_bundle(&args[1..]),
        "hash-object" => cmd_hash_object(&args[1..]),
        "cat-file" => cmd_cat_file(&args[1..]),
        "checkout" => cmd_checkout(&args[1..]),
        "check-attr" => cmd_check_attr(&args[1..]),
        "check-ignore" => cmd_check_ignore(&args[1..]),
        "clean" => cmd_clean(&args[1..]),
        "clone" => cmd_clone(&args[1..]),
        "config" => cmd_config(&args[1..]),
        "count-objects" => cmd_count_objects(&args[1..]),
        "commit" => cmd_commit(&args[1..]),
        "commit-graph" => cmd_commit_graph(&args[1..]),
        "commit-tree" => cmd_commit_tree(&args[1..]),
        "diff" => cmd_diff(&args[1..]),
        "fetch" => cmd_fetch(&args[1..]),
        "for-each-ref" => cmd_for_each_ref(&args[1..]),
        "ls-remote" => cmd_ls_remote(&args[1..]),
        "ls-files" => cmd_ls_files(&args[1..]),
        "ls-tree" => cmd_ls_tree(&args[1..]),
        "log" => cmd_log(&args[1..]),
        "merge-base" => cmd_merge_base(&args[1..]),
        "mktree" => cmd_mktree(&args[1..]),
        "multi-pack-index" => cmd_multi_pack_index(&args[1..]),
        "mv" => cmd_mv(&args[1..]),
        "pack-refs" => cmd_pack_refs(&args[1..]),
        "write-tree" => cmd_write_tree(&args[1..]),
        "worktree" => cmd_worktree(&args[1..]),
        "update-index" => cmd_update_index(&args[1..]),
        "update-ref" => cmd_update_ref(&args[1..]),
        "rev-parse" => cmd_rev_parse(&args[1..]),
        "rev-list" => cmd_rev_list(&args[1..]),
        "reflog" => cmd_reflog(&args[1..]),
        "remote" => cmd_remote(&args[1..]),
        "reset" => cmd_reset(&args[1..]),
        "restore" => cmd_restore(&args[1..]),
        "rm" => cmd_rm(&args[1..]),
        "show-ref" => cmd_show_ref(&args[1..]),
        "stash" => cmd_stash(&args[1..]),
        "submodule" => cmd_submodule(&args[1..]),
        "symbolic-ref" => cmd_symbolic_ref(&args[1..]),
        "status" => cmd_status(&args[1..]),
        "switch" => cmd_switch(&args[1..]),
        "tag" => cmd_tag(&args[1..]),
        "testkit" => cmd_testkit(&args[1..]),
        "version" | "-v" | "--version" => cmd_version(),
        _ => Err(GitError::Command(format!("unsupported command {command}"))),
    }
}

struct GitArgCursor<'a> {
    args: &'a [String],
    position: usize,
}

impl<'a> GitArgCursor<'a> {
    fn new(args: &'a [String]) -> Self {
        Self { args, position: 0 }
    }

    fn next(&mut self) -> Option<&'a str> {
        let value = self.args.get(self.position)?;
        self.position += 1;
        Some(value)
    }

    fn next_value(&mut self) -> Option<&'a str> {
        self.next()
    }

    fn rest(&self) -> &'a [String] {
        &self.args[self.position..]
    }
}

fn long_option_value<'a>(arg: &'a str, option: &str) -> Option<&'a str> {
    let value = arg.strip_prefix("--")?;
    let (name, value) = value.split_once('=')?;
    (name == option).then_some(value)
}

fn cmd_version() -> Result<()> {
    println!("git version {}", git_core::UPSTREAM_GIT_COMPAT_VERSION);
    Ok(())
}

fn cmd_worktree(args: &[String]) -> Result<()> {
    let Some(subcommand) = args.first().map(String::as_str) else {
        eprintln!("error: need a subcommand");
        return worktree_usage();
    };
    match subcommand {
        "add" => cmd_worktree_add(&args[1..]),
        "list" => cmd_worktree_list(&args[1..]),
        "prune" => cmd_worktree_prune(&args[1..]),
        "lock" => cmd_worktree_lock(&args[1..]),
        "move" => cmd_worktree_move(&args[1..]),
        "remove" => cmd_worktree_remove(&args[1..]),
        "repair" => cmd_worktree_repair(&args[1..]),
        "unlock" => cmd_worktree_unlock(&args[1..]),
        _ => {
            eprintln!("error: unknown subcommand: '{subcommand}'");
            worktree_usage()
        }
    }
}

