fn branch_list_patterns_match(patterns: &[String], name: &str, ignore_case: bool) -> bool {
    patterns.is_empty()
        || patterns.iter().any(|pattern| {
            if ignore_case {
                refname_pattern_matches_case(pattern, name, true)
            } else {
                refname_pattern_matches(pattern, name)
            }
        })
}

